 exam=["Registration, recall and recognition memory", "Ask about alcohol intake, vomiting, malnutrition and bariatric surgery", "Ophthalmoplegia and ataxia as accompanying Wernicke signs"],
 pearls=["Small mammillary bodies on MRI in an amnesic patient are the footprint of past Wernicke encephalopathy", "Thiamine before glucose in any malnourished confused patient"],
